using PlayerOne.Windows.Models;using PlayerOne.Windows.Services;namespace PlayerOne.Windows;public partial class LibraryWindow:System.Windows.Window{readonly DeviceAuth auth;readonly long? pid;bool favorites;public LibraryWindow(DeviceAuth a){InitializeComponent();auth=a;pid=PlaylistSelectionStore.Load();Loaded+=(_,__)=>ShowRecents();}void Back_Click(object s,System.Windows.RoutedEventArgs e)=>Close();void ShowRecents(){favorites=false;Items.ItemsSource=PlayerStateStore.Recents(auth,pid).Where(PlayerStateStore.Meaningful).ToList();}void Continue_Click(object s,System.Windows.RoutedEventArgs e)=>ShowRecents();void Favorites_Click(object s,System.Windows.RoutedEventArgs e){favorites=true;Items.ItemsSource=PlayerStateStore.Favorites(auth,pid);}void Open_Click(object s,System.Windows.Input.MouseButtonEventArgs e){if(!favorites&&Items.SelectedItem is RecentEntry r&&r.StreamUrl is not null)new PlayerWindow(auth,new XtreamItem(r.StreamUrl.GetHashCode().ToString(),r.Title,r.Subtitle,r.Image,r.StreamUrl,r.Type,0)).Show();else if(favorites&&Items.SelectedItem is FavoriteEntry f&&f.StreamUrl is not null)new PlayerWindow(auth,new XtreamItem(f.Id,f.Title,f.Subtitle,f.Image,f.StreamUrl,f.Type,0)).Show();}}